    "34201801": { i18n_id: "34201801", i18n_sb: "符箓" },
    "30310601": { i18n_id: "30310601", i18n_sb: "破甲" },
    "30210601": { i18n_id: "30210601", i18n_sb: "鹤翼" },
    "311012401": { i18n_id: "311012401", i18n_sb: "放逐四阶" },
