    "31100501": { i18n_id: "31100501", i18n_sb: "反馈" },
    "32101201": { i18n_id: "32101201", i18n_sb: "空城" },
    "33102701": { i18n_id: "33102701", i18n_sb: "安恤" },
    "35103301": { i18n_id: "35103301", i18n_sb: "血裔" },
    "31102401": { i18n_id: "31102401", i18n_sb: "恂恂" },
    "10000301": { i18n_id: "10000301", i18n_sb: "副本武圣" },
    "34100901": { i18n_id: "34100901", i18n_sb: "化身[乾]" },
    "35100301": { i18n_id: "35100301", i18n_sb: "护驾" },
    "311004302": {
        i18n_id: "311004302",
        i18n_sb: "【洛神】洛神三阶。甄姬可秒掉敌人的绝密武功，属控场技能，主智。行动前易触发，有几率连续多次增加自身造成智力伤害的能力。现三阶状态下，己方另两名武将可享受部分洛神效果的伤害加成。"
    },
    "31101602": {
        i18n_id: "31101602",
        i18n_sb: "【强袭】典韦的舍命保驾之技，自残后可狼性大发，属攻击技能，主攻。行动时一般概率触发，消耗自身少量血，即可对敌方单体造成剧烈伤害。"
    },
    "31201802": { i18n_id: "31201802", i18n_sb: "【才鉴】辛宪英能让敌人群死群伤的智慧，属攻击技能，主智。行动时一般概率触发，可对敌方场上全体造成智力伤害。" },
    "321006302": {
        i18n_id: "321006302",
        i18n_sb: "【武圣】武圣三阶。关羽对弱者可造成额外打击的要诀，属攻击技能，主攻。行动时易触发，可对敌方单体造成攻击伤害；若自身攻击力高于目标，则对其造成额外伤害。现三阶状态下，必定能造成该部分的额外伤害。"
    },
    "32101402": { i18n_id: "32101402", i18n_sb: "【结姻】相传与孙尚香结婚的男性能够延年益寿，属控场技能，主智。行动前易触发，可回复自身和己方1名男性武将一定血量。" },
    "35102002": { i18n_id: "35102002", i18n_sb: "【无言】徐庶的无言忠贞，可使智力大增，属被动技能，主智。装备后，可增加自身智力。" },
    "33100302": {
        i18n_id: "33100302",
        i18n_sb: "【制衡】孙权的内政方针，能让自己加伤或减伤，属控场技能，主攻和防。行动前易触发，可增加自身下一次造成的伤害，或减少自身下一次受到的伤害。"
    },
    "331009102": {
        i18n_id: "331009102",
        i18n_sb: "【连营】连营一阶。陆逊能够秒掉敌人的秘计，属攻击技能，主智。行动时易触发，可对敌方单体造成智力伤害，有几率连续多次施放。现一阶状态下，首次施放的回合将会提前。"
    },
    "331012402": {
        i18n_id: "331012402",
        i18n_sb: "【天义】天义四阶。太史慈的道义，每次可攻击2名敌人，属控场技能，主攻。行动前易触发，可对敌方随机2名场上武将造成攻击伤害。现四阶状态下，可使目标下一次受到的伤害大幅增加。"
    },
    "33202002": { i18n_id: "33202002", i18n_sb: "【直言】能对敌人造成剧烈伤害的能力，属攻击技能，主智。行动时一般概率触发，可对敌方单体造成智力伤害。" },
    "341003102": {
        i18n_id: "341003102",
        i18n_sb: "【离间】离间一阶。貂蝉能让敌方2名男性自相残害的媚术，属控场技能，主智。行动前易触发，可对敌方2名男性武将造成智力伤害。现一阶状态下，首次施放的回合将会提前。"
    },
    "35103102": { i18n_id: "35103102", i18n_sb: "【完暴】贾诩能让敌人体无完肤的战法，属被动技能，主智。装备后，可增加自身智力。" },
    "34202102": { i18n_id: "34202102", i18n_sb: "【死谏】田丰以死明谏之志，能与最弱的敌军同归于尽，属卖血技能，主防。阵亡后，可对场上血最少敌军造成防御伤害。" },
    "30310802": { i18n_id: "30310802", i18n_sb: "【穿刺】以武力取胜的方法之七，已在士兵中普及，属攻击技能，主攻。行动时较困难触发，可对敌方单体造成攻击伤害。" },
    "36100102": { i18n_id: "36100102", i18n_sb: "【经验神书】能使任意技能获得大量提升的神书。在技能升级界面吃掉后，可获得大量技能经验。" },
    "31101402": { i18n_id: "31101402", i18n_sb: "【神速】夏侯渊令敌方脆皮最为惧怕的能力，属控场技能，主攻。行动前易触发，可对敌方血量最少单体造成攻击伤害。" },
    "331013402": {
        i18n_id: "331013402",
        i18n_sb: "【奇袭】甘宁夜袭曹营能给敌人造成深入伤害，属控场技能，主攻。行动前易触发，可对敌方全体造成攻击伤害，同时增加对面敌人下一次受到的伤害。现四阶状态下，奇袭的伤害得以提升。"
    },
    "35100602": { i18n_id: "35100602", i18n_sb: "0" },
    "35101802": { i18n_id: "35101802", i18n_sb: "0" },
    "33101802": {
        i18n_id: "33101802",
        i18n_sb: "【激昂】小霸王孙策独创霸业之心，可秒掉敌方脆皮，属攻击技能，主攻。行动时易触发，有几率连续对敌方单体造成攻击伤害，同时增加自身下一次造成的伤害。"
    },
    "10000102": { i18n_id: "10000102", i18n_sb: "【狂骨】魏延可在攻击的同时吸血，属攻击技能，主攻。行动时一般概率触发，可对敌方单体造成攻击伤害，同时吸收其血量。" },
    "38100502": {
        i18n_id: "38100502",
        i18n_sb: "\\u3010\\u9B54\\u5D29\\u574F\\u3011\\u9B54\\xB7\\u8463\\u5353\\u901A\\u8FC7\\u9152\\u6C60\\u8089\\u6797\\u63D0\\u5347\\u5DF1\\u65B9\\u5BFF\\u547D\\uFF0C\\u5C5E\\u88AB\\u52A8\\u6280\\u80FD\\uFF0C\\u4E3B\\u8840\\u3002\\u88C5\\u5907\\u540E\\uFF0C\\u53EF\\u589E\\u52A0\\u5DF1\\u65B9\\u5168\\u4F53\\u8840\\u91CF\\u3002\\u9B54\\xB7\\u8463\\u5353\\u4F5C\\u4E3A\\u4F19\\u4F34\\u65F6\\u4E5F\\u80FD\\u89E6\\u53D1\\u6280\\u80FD\\u6548\\u679C\\u3002"
    },
    "32201102": { i18n_id: "32201102", i18n_sb: "【祸首】南蛮王孟获祸起南中的好战与自负，属被动技能，主攻和防。装备后，可提升自身的攻击与防御。" },
    "33101102": {
        i18n_id: "33101102",
        i18n_sb: "【追忆】步练师的回忆，消逝时可让己方战友回血并增加伤害，属卖血技能，主智。阵亡时，可回复场上己方全体武将一定血量，同时增加下一次造成的伤害。"
    },
    "34102002": { i18n_id: "34102002", i18n_sb: "【天命】汉献帝刘协的天子之命加持，主智。装备后，可提升自身的智力、防御与血量。" },
