    "35101505": { i18n_id: "35101505", i18n_sb: "增加$1%的攻击力." },
    "32101505": { i18n_id: "32101505", i18n_sb: "回复自身血量,回复值为发动者智力$1%；同时让已方1名武将额外进行一次行动." },
    "32201805": { i18n_id: "32201805", i18n_sb: "造成防御力伤害,伤害系数$1%." },
    "331008405": { i18n_id: "331008405", i18n_sb: "免受本次伤害,同时对目标造成不定量的防御力伤害,伤害系数$2%至$3%." },
    "33101205": { i18n_id: "33101205", i18n_sb: "造成攻击力伤害,伤害系数$1%." },
    "33201605": { i18n_id: "33201605", i18n_sb: "造成防御力伤害,伤害系数$1%." },
    "341002305": { i18n_id: "341002305", i18n_sb: "造成攻击力伤害,伤害系数$1%；目标下一次造成的伤害将减少发动者攻击力的$2%." },
    "34100405": { i18n_id: "34100405", i18n_sb: "回复目标血量,回复总量为发动者智力的$1%." },
    "34200905": { i18n_id: "34200905", i18n_sb: "减少目标下一次所受伤害,减值为发动者智力的$1%." },
    "30310405": { i18n_id: "30310405", i18n_sb: "造成攻击力伤害,伤害系数$1%." },
