    dialogname553019014: { i18n_id: "dialogname553019014", i18n_sb: "王平" },
    dialogname553020022: { i18n_id: "dialogname553020022", i18n_sb: "$UserName" },
    dialogname554008021: { i18n_id: "dialogname554008021", i18n_sb: "典满" },
    dialogname554016013: { i18n_id: "dialogname554016013", i18n_sb: "朱灵" },
    dialogname554018021: { i18n_id: "dialogname554018021", i18n_sb: "$UserName" },
    dialogname554020016: { i18n_id: "dialogname554020016", i18n_sb: "$UserName" },
    dialogdesc550008011: { i18n_id: "dialogdesc550008011", i18n_sb: "太傅病重，谢绝一切访客！" },
    dialogdesc550012017: { i18n_id: "dialogdesc550012017", i18n_sb: "我去，这个节奏该不会是司马懿也快变成反将了吧！我必须去看他！" },
    dialogdesc550016017: { i18n_id: "dialogdesc550016017", i18n_sb: "我这么远过来，你就赶我走，不太好吧。" },
    dialogdesc550018022: { i18n_id: "dialogdesc550018022", i18n_sb: "非礼个节操，你没病啊，那你那么远喊我来干嘛？" },
    dialogdesc550020013: { i18n_id: "dialogdesc550020013", i18n_sb: "他夺权你找他啊！关我什么事？" },
    dialogdesc551004016: { i18n_id: "dialogdesc551004016", i18n_sb: "不服来战！" },
    dialogdesc551012013: { i18n_id: "dialogdesc551012013", i18n_sb: "谋反？难道是野心家？是谁谋反？" },
    dialogdesc551018011: { i18n_id: "dialogdesc551018011", i18n_sb: "魏延将军已被捕！一众将军都发现他谋反的事实！" },
    dialogdesc551019022: { i18n_id: "dialogdesc551019022", i18n_sb: "他死那么冤，八成又被野心家控制了！" },
    dialogdesc552004012: { i18n_id: "dialogdesc552004012", i18n_sb: "我找司马懿，让他给我出来！" },
    dialogdesc552012012: { i18n_id: "dialogdesc552012012", i18n_sb: "侮辱太傅者死！" },
    dialogdesc552018012: { i18n_id: "dialogdesc552018012", i18n_sb: "因为你才能阻止野心家！" },
    dialogdesc552019014: { i18n_id: "dialogdesc552019014", i18n_sb: "三国历史改变了，到底会发生什么可怕的事？" },
    dialogdesc552020012: { i18n_id: "dialogdesc552020012", i18n_sb: "我现在说什么你都不会相信我，既然是我召唤你来的，就让我在这里把你解决吧！" },
    dialogdesc553004014: { i18n_id: "dialogdesc553004014", i18n_sb: "我不会拿那么多兵马，只听顾问的一面之词就去冒险！" },
    dialogdesc553012013: { i18n_id: "dialogdesc553012013", i18n_sb: "（黑影）你很快就能知道了……" },
    dialogdesc553018012: { i18n_id: "dialogdesc553018012", i18n_sb: "你到底是谁？我不和神秘人合作！" },
    dialogdesc553019014: { i18n_id: "dialogdesc553019014", i18n_sb: "军师说，他死以后，七星灯已被封印，防止有人用作他途。" },
    dialogdesc553020022: { i18n_id: "dialogdesc553020022", i18n_sb: "为什么野心家想和我合作？难道他需要我的帮助才能改变三国历史？" },
    dialogdesc554008021: { i18n_id: "dialogdesc554008021", i18n_sb: "此战你只是侥幸获胜，你一定逃不出这里！" },
    dialogdesc554016013: { i18n_id: "dialogdesc554016013", i18n_sb: "不如再进行一次强攻，说不定就赢了呢。" },
    dialogdesc554018021: { i18n_id: "dialogdesc554018021", i18n_sb: "难道不管我怎么做，都没办法挽救蜀国了？" },
    dialogdesc554020016: { i18n_id: "dialogdesc554020016", i18n_sb: "帮司马家族做事？！我宁死也不愿意！开打吧！" },
