    "31101401": { i18n_id: "31101401", i18n_sb: "神速" },
    "331013401": { i18n_id: "331013401", i18n_sb: "奇袭四阶" },
    "35100601": { i18n_id: "35100601", i18n_sb: "颂威" },
    "35101801": { i18n_id: "35101801", i18n_sb: "若愚" },
    "33101801": { i18n_id: "33101801", i18n_sb: "激昂" },
    "10000101": { i18n_id: "10000101", i18n_sb: "副本狂骨" },
    "38100501": { i18n_id: "38100501", i18n_sb: "魔崩坏" },
    "32201101": { i18n_id: "32201101", i18n_sb: "祸首" },
    "33101101": { i18n_id: "33101101", i18n_sb: "追忆" },
    "34102001": { i18n_id: "34102001", i18n_sb: "天命" },
    "311004502": {
        i18n_id: "311004502",
        i18n_sb: "【洛神】洛神五阶。甄姬可秒掉敌人的绝密武功，属控场技能，主智。行动前易触发，有几率连续多次增加己方全体造成智力伤害的能力，并提升自身单体的防御能力。现五阶状态下，洛神的伤害加成将大幅提升。"
    },
    "31102102": { i18n_id: "31102102", i18n_sb: "【贞烈】王异与敌人同归于尽的决心，属卖血技能，主防。阵亡时，可对敌方单体造成剧烈防御伤害。" },
    "31202002": { i18n_id: "31202002", i18n_sb: "【肃整】朱灵能让敌人受到深入打击的治军之道，属控场技能，主智。行动前易触发，可使敌方单体下一次受到的伤害增加。" },
    "321006502": {
        i18n_id: "321006502",
        i18n_sb: "【武圣】武圣五阶。关羽对弱者可造成额外打击的要诀，属攻击技能，主攻。行动时易触发，可对敌方单体造成攻击伤害。现五阶状态下，若武圣击毙了敌人则施放者可再行动一回合。"
    },
    "321014202": {
        i18n_id: "321014202",
        i18n_sb: "【结姻】结姻二阶。相传与孙尚香结婚的男性能够延年益寿，属控场技能，主智。行动前易触发，可回复自身和己方1名男性武将一定血量。现二阶状态下，结姻目标下一次造成的伤害将增加。"
    },
    "32201002": { i18n_id: "32201002", i18n_sb: "【当先】廖化能够先下手为强的秘诀，属控场技能，主攻。行动前易触发，可对敌方单体造成连续两次攻击伤害。" },
    "33100802": { i18n_id: "33100802", i18n_sb: "【天香】能让小乔免伤并反弹给敌人的魅力，属卖血技能，主防。受伤前易触发，可免受本次伤害，同时对敌方单体造成防御伤害。" },
    "331009302": {
        i18n_id: "331009302",
        i18n_sb: "【连营】连营三阶。陆逊能够秒掉敌人的秘计，属攻击技能，主智。行动时易触发，可对敌方单体造成智力伤害，有几率连续多次施放。现三阶状态下，连营连续施放的概率将提升。"
    },
    "33101502": { i18n_id: "33101502", i18n_sb: "【不屈】周泰的性格，战场中可屹立不倒，属卖血技能，主防。血量为0时必定触发，可承受额外伤害。" },
    "33202202": { i18n_id: "33202202", i18n_sb: "【独进】能够反击敌人的力量，属卖血技能，主防。受伤后一般概率触发，可对敌方单体造成防御伤害。" },
    "341003302": {
        i18n_id: "341003302",
        i18n_sb: "【离间】离间三阶。貂蝉能让敌方2名男性自相残害的媚术，属控场技能，主智。行动前易触发，可对敌方2名男性武将造成智力伤害。现三阶状态下，可使自己下次受到的伤害减少。"
    },
    "34101202": { i18n_id: "34101202", i18n_sb: "【乱击】大嘴袁绍可对敌人全军造成干扰的秘术，属攻击技能，主智。行动时易触发，可对敌方场上全体造成智力伤害。" },
    "34202202": {
        i18n_id: "34202202",
        i18n_sb: "【狂斧】潘凤能使敌人伤害减弱的伎俩，属控场技能，主攻。行动前一般概率触发，可对敌方单体造成攻击伤害，同时减少其下一次造成的伤害。"
    },
    "30311002": { i18n_id: "30311002", i18n_sb: "【击溃】以武力取胜的方法之九，已在士兵中普及，属攻击技能，主攻。行动时较困难触发，可对敌方单体造成攻击伤害。" },
    "36300102": { i18n_id: "36300102", i18n_sb: "【经验银书】能使任意技能获得少量提升的银书。在技能升级界面吃掉后，可获得少量技能经验。" },
    "32101702": {
        i18n_id: "32101702",
        i18n_sb: "【涅槃】浴火重生，凤雏岂能消亡，属卖血技能，主智。受伤后易触发，增加自身下一次造成的伤害；阵亡时仅限一次，可重置自身血量并复活。"
    },
    "33101402": { i18n_id: "33101402", i18n_sb: "【苦肉】黄盖的苦肉之计，越受伤越强悍，属控场技能，主攻。行动前易触发，有几率连续多次消耗自身血量，用以增加自身攻击力。" },
    "31101702": {
        i18n_id: "31101702",
        i18n_sb: "【巧变】张郃随机应对战场万千变化的用兵之道，属控场技能，主攻。行动前一般概率触发，可增加敌方单体下一次受到的伤害，并在自己行动后使其无法行动2回合。"
    },
    "32102002": {
        i18n_id: "32102002",
        i18n_sb: "【挑衅】麒麟儿姜维胆大如斗，凭以过人的文武之才使出的战术：对敌方大胆挑衅，施展一次佯攻并做好万全应对之策。属攻击技能，主智。行动时易触发，可提升自身下一回合的防御能力并对敌方全体造成智力伤害，同时下一回合敌方武将只能选择挑衅者为攻击目标。"
    },
    "33200102": { i18n_id: "33200102", i18n_sb: "0" },
    "34200602": { i18n_id: "34200602", i18n_sb: "【耀武】华雄能带领小伙伴生存的能力，属卖血技能，主防。受伤后易触发，可为血最少的友军回复血量。" },
    "35103502": { i18n_id: "35103502", i18n_sb: "【神戟】邪神吕布怒火迸发、一骑当千。不仅提升自身战斗力，更极大扩大了攻击范围。" },
    "32202502": { i18n_id: "32202502", i18n_sb: "【象战】南蛮人掌握驭兽之道，善以猛兽战法主导战局，令对手闻风丧胆，主攻和防。装备后，可提升自身的攻击与防御。" },
    "371014102": {
        i18n_id: "371014102",
        i18n_sb: "【嗜血一阶】德古拉魏延可在攻击的同时吸血，且对血的共鸣会渐渐提升，属攻击技能，主攻。行动时易触发，可对敌方单体造成攻击伤害，同时吸收其血量，吸血量将随技能等级而提升。现一阶状态下，首次施放的回合将会提前。"
    },
    "35103602": {
        i18n_id: "35103602",
        i18n_sb: "\\u3010\\u6D89\\u730E\\u3011\\u58EB\\u522B\\u4E09\\u65E5\\uFF0C\\u5373\\u66F4\\u522E\\u76EE\\u76F8\\u5F85\\uFF0C\\u5982\\u4ECA\\u7684\\u795E\\xB7\\u5415\\u8499\\u535A\\u5B66\\u6D3D\\u95FB\\u3001\\u6D89\\u730E\\u751A\\u5E7F\\u3002\\u8BE5\\u6280\\u80FD\\u4E3B\\u667A\\u548C\\u9632\\uFF0C\\u88C5\\u5907\\u540E\\uFF0C\\u53EF\\u63D0\\u5347\\u81EA\\u8EAB\\u7684\\u667A\\u529B\\u4E0E\\u9632\\u5FA1\\u3002"
    },
