    itemdesc311007: { i18n_id: "itemdesc311007", i18n_sb: "【刚烈】获得夏侯惇有仇必报的性格，属卖血技能，主防。受伤后易触发，可立即对敌方单体造成伤害。" },
    itemdesc312010: { i18n_id: "itemdesc312010", i18n_sb: "【援护】曹洪对血最少友军的援助，属控场技能，主攻。行动前易触发，可为场上己方血最少的人回复一定血量。" },
    itemdesc321004: {
        i18n_id: "itemdesc321004",
        i18n_sb: "【仁德】刘备收买人心的手段，既能增加友军输出，又能回复自身血量，属控场技能，主攻。行动前易触发，可回复自身一定血量，同时让1名己方武将下一次造成的伤害增加。"
    },
    itemdesc321016: { i18n_id: "itemdesc321016", i18n_sb: "【狂骨】魏延可在攻击的同时吸血，属攻击技能，主攻。行动时一般概率触发，可对敌方单体造成攻击伤害，同时吸收其血量。" },
    itemdesc322019: {
        i18n_id: "itemdesc322019",
        i18n_sb: "【忠勇】获得周仓的品格，能够默默保护血最少的己方战友，属控场技能，主攻。行动前易触发，可减少场上血最少己方武将下一次受到的伤害。"
    },
    itemdesc331008: {
        i18n_id: "itemdesc331008",
        i18n_sb: "【天香】能让小乔免伤并反弹给敌人的魅力，属卖血技能，主防。受伤前易触发，可免受本次伤害，同时对敌方单体造成防御伤害。"
    },
    itemdesc332018: { i18n_id: "itemdesc332018", i18n_sb: "【剑舞】不怕死的绝技，血最多的敌人最怕此技，属卖血技能，主防。阵亡时，可对场上血最多敌军造成防御伤害。" },
    itemdesc341007: {
        i18n_id: "itemdesc341007",
        i18n_sb: "【无前】吕玲绮仅凭才智便可让敌方全军错乱的能力，属攻击技能，主智。行动时一般概率触发，可对敌方场上全体造成智力伤害。"
    },
    itemdesc342010: { i18n_id: "itemdesc342010", i18n_sb: "【血殇】能使人攻击性暴增的力量，属攻击技能，主攻。行动时一般概率触发，可对敌方单体造成攻击伤害。" },
    itemdesc303105: { i18n_id: "itemdesc303105", i18n_sb: "【谋害】以智力取胜的方法，已在士兵中普及，属攻击技能，主智。行动时较困难触发，可对敌方单体造成智力伤害。" },
    itemdesc302105: { i18n_id: "itemdesc302105", i18n_sb: "【鱼鳞】能使人增加防御力的阵法，属被动技能，主防。装备后，可增加自身防御力。" },
    itemdesc351016: { i18n_id: "itemdesc351016", i18n_sb: "【八阵】孔明所创的防御阵法，属被动技能，主防。装备后，可增加自身防御力。" },
