    dialogname551020011: { i18n_id: "dialogname551020011", i18n_sb: "德古拉魏延" },
    dialogname552004013: { i18n_id: "dialogname552004013", i18n_sb: "夏侯惇" },
    dialogname552012013: { i18n_id: "dialogname552012013", i18n_sb: "$UserName" },
    dialogname552018013: { i18n_id: "dialogname552018013", i18n_sb: "$UserName" },
    dialogname552019015: { i18n_id: "dialogname552019015", i18n_sb: "司马懿" },
    dialogname552020013: { i18n_id: "dialogname552020013", i18n_sb: "$UserName" },
    dialogname553004015: { i18n_id: "dialogname553004015", i18n_sb: "$UserName" },
    dialogname553012014: { i18n_id: "dialogname553012014", i18n_sb: "伊籍" },
    dialogname553018013: { i18n_id: "dialogname553018013", i18n_sb: "\\u9B54\\xB7\\u9A6C\\u8D85" },
    dialogname553019015: { i18n_id: "dialogname553019015", i18n_sb: "$UserName" },
    dialogname554004011: { i18n_id: "dialogname554004011", i18n_sb: "$UserName" },
    dialogname554008022: { i18n_id: "dialogname554008022", i18n_sb: "$UserName" },
    dialogname554016014: { i18n_id: "dialogname554016014", i18n_sb: "$UserName" },
    dialogname554019011: { i18n_id: "dialogname554019011", i18n_sb: "张春华" },
    dialogname554020021: { i18n_id: "dialogname554020021", i18n_sb: "程昱" },
    dialogdesc550008012: { i18n_id: "dialogdesc550008012", i18n_sb: "看清楚，我有他的亲笔信，是他让我来探望的~！" },
    dialogdesc550012018: { i18n_id: "dialogdesc550012018", i18n_sb: "擅入内宫者死！" },
    dialogdesc550016018: { i18n_id: "dialogdesc550016018", i18n_sb: "那我就只能用武力解决了！" },
    dialogdesc550018023: { i18n_id: "dialogdesc550018023", i18n_sb: "我是提醒你一句，现在和我合作还来得及。" },
    dialogdesc550020014: { i18n_id: "dialogdesc550020014", i18n_sb: "你是帮凶！" },
    dialogdesc551004021: { i18n_id: "dialogdesc551004021", i18n_sb: "就算我出国的手续不专业，你可以指点我嘛，也不用一上来就动手动脚！" },
    dialogdesc551012014: { i18n_id: "dialogdesc551012014", i18n_sb: "魏延！" },
    dialogdesc551018012: { i18n_id: "dialogdesc551018012", i18n_sb: "三人成虎，你们这么多人说他谋反！他有口难辩！" },
    dialogdesc551020011: { i18n_id: "dialogdesc551020011", i18n_sb: "谁敢杀我！谁敢杀我！！" },
    dialogdesc552004013: { i18n_id: "dialogdesc552004013", i18n_sb: "司马太傅重病，不见外客！" },
    dialogdesc552012013: { i18n_id: "dialogdesc552012013", i18n_sb: "现在每个人都想我死，我好想给自己点个赞啊！" },
    dialogdesc552018013: { i18n_id: "dialogdesc552018013", i18n_sb: "我为什么要阻止他？就因为他会改变三国历史吗？就算三国历史真的被改变了，又和我有什么关系？" },
    dialogdesc552019015: { i18n_id: "dialogdesc552019015", i18n_sb: "我的家族，可能无法继承魏国，进而无法开创晋国。" },
    dialogdesc552020013: { i18n_id: "dialogdesc552020013", i18n_sb: "好！杀了你，我就能回到现实世界！" },
    dialogdesc553004015: { i18n_id: "dialogdesc553004015", i18n_sb: "既然你敢抗命，就别怪我收拾你！" },
    dialogdesc553012014: { i18n_id: "dialogdesc553012014", i18n_sb: "攻打魏国之事还需从长计议，请顾问三思！" },
    dialogdesc553018013: { i18n_id: "dialogdesc553018013", i18n_sb: "（黑影）你认识我们……七星连璧，阴阳合开……" },
    dialogdesc553019015: { i18n_id: "dialogdesc553019015", i18n_sb: "既然你不给我，我就只能用抢的了……" },
    dialogdesc554004011: {
        i18n_id: "dialogdesc554004011",
        i18n_sb: "野心家竟然主动想和我合作，他难道不知道我被召唤到这个游戏的目的就是弄死他吗，他这么做，到底有什么阴谋？再说已经六年没打仗了，我暂时不和他合作，也没关系。"
    },
    dialogdesc554008022: { i18n_id: "dialogdesc554008022", i18n_sb: "别学狗叫了，我听不懂~~" },
    dialogdesc554016014: { i18n_id: "dialogdesc554016014", i18n_sb: "看我把你们打跪爬回去！" },
    dialogdesc554019011: { i18n_id: "dialogdesc554019011", i18n_sb: "程昱军师才进成都，蜀后主已大开城门投降！" },
    dialogdesc554020021: { i18n_id: "dialogdesc554020021", i18n_sb: "蜀国亡了，你的蜀国真监国职务也自动免除了，今后你好自为之吧" },
    "4410170401": { i18n_id: "4410170401", i18n_sb: "四世三公" },
