    "8110310301": { i18n_id: "8110310301", i18n_sb: "突破界限" },
    "22101501": { i18n_id: "22101501", i18n_sb: "桃之夭夭" },
    "342013501": { i18n_id: "342013501", i18n_sb: "惴恐五阶" },
    "342013502": {
        i18n_id: "342013502",
        i18n_sb: "【惴恐五阶】伏皇后处于深宫之中，对于曹操挟制天子而惴惴不安。属攻击技能，主智，行动时易触发，对敌方单体造成智力伤害，若自身智力高于目标则造成额外的无视防御伤害并必定产生暴击，暴击伤害200%。现五阶状态下，当自身智力高于目标时，将敌方的武将牌翻面。"
    },
    "342013503": { i18n_id: "342013503", i18n_sb: "行动时 易触发" },
    "342013504": { i18n_id: "342013504", i18n_sb: "敌方单体" },
