    "32102201": { i18n_id: "32102201", i18n_sb: "征南" },
    "35102501": { i18n_id: "35102501", i18n_sb: "制霸" },
    "10000201": { i18n_id: "10000201", i18n_sb: "副本绝情" },
    "34100101": { i18n_id: "34100101", i18n_sb: "神愤" },
    "34200801": { i18n_id: "34200801", i18n_sb: "影兵" },
    "37101401": { i18n_id: "37101401", i18n_sb: "嗜血" },
    "33100201": { i18n_id: "33100201", i18n_sb: "攻心" },
    "35100402": { i18n_id: "35100402", i18n_sb: "【倾国】能让甄姬长久不败的魅力所在，属被动技能，主防。装备后，可增加自身防御力。" },
    "35100802": { i18n_id: "35100802", i18n_sb: "【秘计】让王异热血沸腾的退敌之计，属被动技能，主血。装备后，可增加自身血量。" },
    "31202102": { i18n_id: "31202102", i18n_sb: "【峻刑】满宠的执法之道，能扼制攻击最高的敌人，属控场技能，主智。行动前易触发，可使场上攻最高敌军下一次造成伤害减少。" },
    "32100702": { i18n_id: "32100702", i18n_sb: "【咆哮】张飞喝退敌军之技，能连续多次伤敌，属攻击技能，主攻。行动时易触发，可对敌方单体造成连续多次攻击伤害。" },
    "321014302": {
        i18n_id: "321014302",
        i18n_sb: "【结姻】结姻三阶。相传与孙尚香结婚的男性能够延年益寿，属控场技能，主智。行动前易触发，可回复自身和己方1名男性武将一定血量。现三阶状态下，结姻目标下一次造成的伤害将大幅增加。"
    },
    "32201602": { i18n_id: "32201602", i18n_sb: "【燕语】能抗锤子的女人，自然一个顶三个，属攻击技能，主攻。行动时一般概率触发，可对敌方场上全体造成攻击伤害。" },
    "331008102": {
        i18n_id: "331008102",
        i18n_sb: "【天香】能让小乔免伤并反弹给敌人的魅力，属卖血技能，主防。受伤前易触发，可免受本次伤害，同时对敌方单体造成防御伤害。现一阶状态下，首次施放的回合将会提前。"
    },
    "331009402": {
        i18n_id: "331009402",
        i18n_sb: "【连营】连营四阶。陆逊能够秒掉敌人的秘计，属攻击技能，主智。行动时易触发，可对敌方单体造成智力伤害，有几率连续多次施放。现四阶状态下，连营连续施放的概率将较大提升。"
    },
    "33201002": { i18n_id: "33201002", i18n_sb: "【虎娇】大虎卖萌时可使敌人伤及一片，属攻击技能，主智。行动时一般概率触发，可对敌方全体造成智力伤害。" },
    "34100202": { i18n_id: "34100202", i18n_sb: "【无双】吕布能一招扫灭敌方全军的能力，属攻击技能，主攻。行动时易触发，可对敌方场上全体造成攻击伤害。" },
    "341003402": {
        i18n_id: "341003402",
        i18n_sb: "【离间】离间四阶。貂蝉能让敌方2名男性自相残害的媚术，属控场技能，主智。行动前易触发，可对敌方2名男性武将造成智力伤害。现四阶状态下，可使自己下次受到的伤害大幅减少。"
    },
    "34200702": {
        i18n_id: "34200702",
        i18n_sb: "【焚城】火烧洛阳之策，能让敌军受到更深的伤害，属攻击技能，主智。行动时一般概率触发，可对敌方场上全体造成智力伤害，同时增加其下一次受到的伤害。"
    },
    "30310102": { i18n_id: "30310102", i18n_sb: "【重装】以武力取胜的方法之一，已在士兵中普及，属攻击技能，主攻。行动时较困难触发，可对敌方单体造成攻击伤害。" },
    "30210102": { i18n_id: "30210102", i18n_sb: "【北斗】能使人增加攻击力的阵法，属被动技能，主攻。装备后，可增加自身攻击力。" },
    "31100602": { i18n_id: "31100602", i18n_sb: "【突袭】张辽爆发后的能力，每次可攻击2名敌人，属控场技能，主攻。行动前易触发，可增加自身伤害的同时，减少目标下一次造成的伤害。" },
    "35102202": { i18n_id: "35102202", i18n_sb: "【英姿】美周郎飒爽迷人的不世之姿，属控场技能，主智。行动前易触发，可减少自身下一次受到的伤害，同时增加自身下一次造成的伤害。" },
    "33101702": {
        i18n_id: "33101702",
        i18n_sb: "【旋风】凌统能削弱2名敌人的能力，属控场技能，主攻。行动后易触发，可对敌方随机2名场上武将造成攻击伤害，同时减少其下一次造成的伤害。"
    },
    "31101802": {
        i18n_id: "31101802",
        i18n_sb: "【断粮】徐晃截源断粮以奇克敌的战场发挥，属攻击技能，主攻。行动时易触发，可对敌方单体造成攻击伤害，并使其下一次的生命值回复量减少。"
    },
    "33100102": { i18n_id: "33100102", i18n_sb: "【炎神】获得上古炎神之助，使智力及血量大增，属被动技能，主智和血。装备后，可增加自身的智力和血量。" },
    "33200202": { i18n_id: "33200202", i18n_sb: "0" },
    "38100302": {
        i18n_id: "38100302",
        i18n_sb: "\\u3010\\u9B54\\u94C1\\u9A91\\u3011\\u9B54\\xB7\\u9A6C\\u8D85\\u53D7\\u4F24\\u540E\\u53EF\\u9B54\\u6027\\u5927\\u53D1\\uFF0C\\u65A9\\u654C\\u4E00\\u7247\\uFF0C\\u5C5E\\u5356\\u8840\\u6280\\u80FD\\uFF0C\\u4E3B\\u9632\\u3002\\u53D7\\u4F24\\u540E\\u6613\\u89E6\\u53D1\\uFF0C\\u53EF\\u5BF9\\u654C\\u65B9\\u5168\\u4F53\\u9020\\u6210\\u9632\\u5FA1\\u529B\\u4F24\\u5BB3\\u3002"
    },
    "37100502": { i18n_id: "37100502", i18n_sb: "【圣弓】黄忠百发百中直取敌方要害的弓术，属攻击技能，主攻。行动时易触发，可对场上防最低敌军造成攻击伤害。" },
    "33101902": { i18n_id: "33101902", i18n_sb: "【弘援】诸葛瑾弘缓雍雅、大度善思，穷尽自己的才能以保友邦免于危难，属被动技能，主防。装备后，可提升己方全体防御。" },
    "371014202": {
        i18n_id: "371014202",
        i18n_sb: "【嗜血二阶】德古拉魏延可在攻击的同时吸血，且对血的共鸣会渐渐提升，属攻击技能，主攻。行动时易触发，可对敌方单体造成攻击伤害，同时吸收其血量，吸血量将随技能等级而提升。现二阶状态下，首次施放的回合将会大幅提前。"
    },
