    dialogname551020012: { i18n_id: "dialogname551020012", i18n_sb: "$UserName" },
    dialogname552004014: { i18n_id: "dialogname552004014", i18n_sb: "$UserName" },
    dialogname552012021: { i18n_id: "dialogname552012021", i18n_sb: "$UserName" },
    dialogname552018014: { i18n_id: "dialogname552018014", i18n_sb: "司马懿" },
    dialogname552019016: { i18n_id: "dialogname552019016", i18n_sb: "$UserName" },
    dialogname552020021: { i18n_id: "dialogname552020021", i18n_sb: "$UserName" },
    dialogname553004021: { i18n_id: "dialogname553004021", i18n_sb: "$UserName" },
    dialogname553012015: { i18n_id: "dialogname553012015", i18n_sb: "$UserName" },
    dialogname553018014: { i18n_id: "dialogname553018014", i18n_sb: "$UserName" },
    dialogname553019021: { i18n_id: "dialogname553019021", i18n_sb: "$UserName" },
    dialogname554004012: { i18n_id: "dialogname554004012", i18n_sb: "\\u9B54\\xB7\\u9A6C\\u8D85" },
    dialogname554012011: { i18n_id: "dialogname554012011", i18n_sb: "$UserName" },
    dialogname554016021: { i18n_id: "dialogname554016021", i18n_sb: "$UserName" },
    dialogname554019012: { i18n_id: "dialogname554019012", i18n_sb: "$UserName" },
    dialogname554020022: { i18n_id: "dialogname554020022", i18n_sb: "$UserName" },
    dialogdesc550008013: { i18n_id: "dialogdesc550008013", i18n_sb: "我国太傅怎么可能和蜀国顾问通信，必是伪造！看我戳穿你！" },
    dialogdesc550012021: { i18n_id: "dialogdesc550012021", i18n_sb: "你国这么大官病了，怎么也没人关心一下，太不像话了！" },
    dialogdesc550016021: { i18n_id: "dialogdesc550016021", i18n_sb: "看个病人都这么难，你们防备心也太强了！" },
    dialogdesc550018024: {
        i18n_id: "dialogdesc550018024",
        i18n_sb: "我被你弄进这个世界，貂蝉死了，野心家到现在没找到，和你合作我很吃亏啊，这种上当受骗又倒霉的事我是再也不干了。"
    },
    dialogdesc550020015: { i18n_id: "dialogdesc550020015", i18n_sb: "我们还是用对打的交流方式决定胜负吧！" },
    dialogdesc551008011: { i18n_id: "dialogdesc551008011", i18n_sb: "听说司马懿夺权，曹爽已死，正是魏国大乱之期，我们应该趁机进攻！" },
    dialogdesc551012015: { i18n_id: "dialogdesc551012015", i18n_sb: "魏延是一代忠臣，你们冤枉他了！" },
    dialogdesc551018013: { i18n_id: "dialogdesc551018013", i18n_sb: "请顾问不要参与谋反之事！" },
    dialogdesc551020012: { i18n_id: "dialogdesc551020012", i18n_sb: "看样子是想当的怨念啊……" },
    dialogdesc552004014: { i18n_id: "dialogdesc552004014", i18n_sb: "他不会又装病吧！今天不管他是死是活，我都必须见到他！闪开！" },
    dialogdesc552012021: { i18n_id: "dialogdesc552012021", i18n_sb: "别在我背后捅刀子，否则我没死你就该死。" },
    dialogdesc552018014: { i18n_id: "dialogdesc552018014", i18n_sb: "我不能告诉你。" },
    dialogdesc552019016: { i18n_id: "dialogdesc552019016", i18n_sb: "没了？" },
    dialogdesc552020021: { i18n_id: "dialogdesc552020021", i18n_sb: "你不是野心家！告诉我！野心家是谁！我怎么才能离开这个该死的地方！" },
    dialogdesc553004021: { i18n_id: "dialogdesc553004021", i18n_sb: "蜀国现在兵困马乏，要说服他们，还真是一个难题。" },
    dialogdesc553012015: { i18n_id: "dialogdesc553012015", i18n_sb: "打仗这种事情如果只停留在想法阶段就完了！别拦我！" },
