    dialogname551008012: { i18n_id: "dialogname551008012", i18n_sb: "$UserName" },
    dialogname551012016: { i18n_id: "dialogname551012016", i18n_sb: "鲍勋" },
    dialogname551018014: { i18n_id: "dialogname551018014", i18n_sb: "$UserName" },
    dialogname551020013: { i18n_id: "dialogname551020013", i18n_sb: "德古拉魏延" },
    dialogname552004021: { i18n_id: "dialogname552004021", i18n_sb: "夏侯惇" },
    dialogname552016011: { i18n_id: "dialogname552016011", i18n_sb: "司马懿" },
    dialogname552018015: { i18n_id: "dialogname552018015", i18n_sb: "$UserName" },
    dialogname552019017: { i18n_id: "dialogname552019017", i18n_sb: "司马懿" },
    dialogname552020022: { i18n_id: "dialogname552020022", i18n_sb: "司马懿" },
    dialogname553008011: { i18n_id: "dialogname553008011", i18n_sb: "$UserName" },
    dialogname553012021: { i18n_id: "dialogname553012021", i18n_sb: "伊籍" },
    dialogname553018015: { i18n_id: "dialogname553018015", i18n_sb: "严颜" },
    dialogname553020011: { i18n_id: "dialogname553020011", i18n_sb: "$UserName" },
    dialogname554004013: { i18n_id: "dialogname554004013", i18n_sb: "$UserName" },
    dialogname554012012: { i18n_id: "dialogname554012012", i18n_sb: "牛金" },
    dialogname554016022: { i18n_id: "dialogname554016022", i18n_sb: "朱灵" },
    dialogname554019013: { i18n_id: "dialogname554019013", i18n_sb: "张春华" },
    dialogdesc550004011: { i18n_id: "dialogdesc550004011", i18n_sb: "小诸葛也死了，他也是被野心家控制的反将，只是……他临死前到底说什么啊……那几个字我完全看不懂啊！！！" },
    dialogdesc550008021: { i18n_id: "dialogdesc550008021", i18n_sb: "如果野心家真的存在的话，能升级一下这个世界将领的大脑吗，版本太低，没办法交流啊！" },
    dialogdesc550012022: { i18n_id: "dialogdesc550012022", i18n_sb: "满朝文武甚至陛下都说，太傅不是真病……" },
    dialogdesc550018011: { i18n_id: "dialogdesc550018011", i18n_sb: "喂，听说你病得都爬不起来，什么情况？" },
    dialogdesc550019011: { i18n_id: "dialogdesc550019011", i18n_sb: "不许走！" },
    dialogdesc550020021: { i18n_id: "dialogdesc550020021", i18n_sb: "曹爽被杀，我魏国的大权，就全落在司马懿手里了……" },
    dialogdesc551008012: { i18n_id: "dialogdesc551008012", i18n_sb: "你傻啊！小诸葛挺进中原的惨败还没恢复过来，你还要去打魏国？拿什么去打？" },
    dialogdesc551012016: { i18n_id: "dialogdesc551012016", i18n_sb: "早就看你不爽了，又不是蜀国人，却当什么真监国，我看魏延谋反你也有份！一起收拾了！" },
    dialogdesc551018014: { i18n_id: "dialogdesc551018014", i18n_sb: "你们越是不让我参与，我偏要参与！让开！" },
    dialogdesc551020013: { i18n_id: "dialogdesc551020013", i18n_sb: "我忠心为国，到头来却落得如此下场！" },
    dialogdesc552004021: { i18n_id: "dialogdesc552004021", i18n_sb: "司马太傅已下命令，如你硬要闯入见他，杀无赦！" },
    dialogdesc552016011: { i18n_id: "dialogdesc552016011", i18n_sb: "竟被你找到这里，你也不容易。" },
    dialogdesc552018015: { i18n_id: "dialogdesc552018015", i18n_sb: "……" },
    dialogdesc552019017: { i18n_id: "dialogdesc552019017", i18n_sb: "没了。" },
    dialogdesc552020022: { i18n_id: "dialogdesc552020022", i18n_sb: "哈哈哈！你永远没办法离开这里！" },
    dialogdesc553008011: { i18n_id: "dialogdesc553008011", i18n_sb: "（吟诗）冥昭瞢闇，谁能极之？考功就前，永遏羽山；这些诗都什么意思？" },
    dialogdesc553012021: { i18n_id: "dialogdesc553012021", i18n_sb: "蜀国必灭于你手！" },
    dialogdesc553018015: { i18n_id: "dialogdesc553018015", i18n_sb: "别想碰军师的任何遗物！我是不会交给你的！" },
    dialogdesc553020011: { i18n_id: "dialogdesc553020011", i18n_sb: "马超？！野心家是你？！" },
    dialogdesc554004013: { i18n_id: "dialogdesc554004013", i18n_sb: "什么声音？战斗号角声？！怎么都到剑阁门外了？" },
    dialogdesc554012012: {
        i18n_id: "dialogdesc554012012",
        i18n_sb: "你又何苦死守这里？先帝一直向我们夸你，说你文武双全，华夏闻名，现在蜀国一个牛人也没有，你还不如来我们这发扬光大！"
    },
    dialogdesc554016022: { i18n_id: "dialogdesc554016022", i18n_sb: "你别得意的太早，吾大魏国必胜！" },
    dialogdesc554019013: { i18n_id: "dialogdesc554019013", i18n_sb: "剑阁已破，想跑，没那么容易！" },
