    "311004405": { i18n_id: "311004405", i18n_sb: "有几率连续多次施放,每施放一次,下一次伤害增加智力$1%；最后能减少自身下一次受到的伤害，减少值为智力的$7%." },
    "34101105": { i18n_id: "34101105", i18n_sb: "造成防御力伤害,伤害系数$2%,同时永久封印目标(无法施放技能)." },
    "31201905": { i18n_id: "31201905", i18n_sb: "造成防御力伤害,伤害系数$1%." },
    "321006405": { i18n_id: "321006405", i18n_sb: "造成攻击力伤害,伤害系数$1%." },
    "321014105": { i18n_id: "321014105", i18n_sb: "回复目标血量,回复值为发动者智力的$1%." },
    "32200905": { i18n_id: "32200905", i18n_sb: "造成攻击力伤害,伤害系数$1%;如果目标血量低于30%,额外造成伤害,伤害系数$2%." },
    "33100705": { i18n_id: "33100705", i18n_sb: "免受本次伤害,同时对目标造成防御力伤害,伤害系数$2%." },
    "331009205": { i18n_id: "331009205", i18n_sb: "造成智力伤害,伤害系数$1%,有几率多次释放." },
    "331012505": { i18n_id: "331012505", i18n_sb: "造成攻击力伤害,伤害系数$1%；并使目标下一次受到的伤害增加，增加值为$2%；目标有概率无法行动一回合." },
    "33202105": { i18n_id: "33202105", i18n_sb: "造成防御力伤害,伤害系数$1%." },
    "341003205": { i18n_id: "341003205", i18n_sb: "造成智力伤害,伤害系数$1%." },
    "35103205": { i18n_id: "35103205", i18n_sb: "增加$1%的防御力." },
    "35300405": { i18n_id: "35300405", i18n_sb: "增加$1%的防御力." },
    "30310905": { i18n_id: "30310905", i18n_sb: "造成攻击力伤害,伤害系数$1%." },
    "36200105": { i18n_id: "36200105", i18n_sb: "可获得中量技能经验." },
    "32101305": { i18n_id: "32101305", i18n_sb: "造成智力伤害,伤害系数$1%." },
    "331013505": {
        i18n_id: "331013505",
        i18n_sb: "造成攻击力伤害,伤害系数$3%，并增加目标下一次受到的伤害，增加值为发动者攻击力的$4%；对面目标额外受到$1%伤害,下一次受到的伤害额外增加值为发动者攻击力的$2%。"
    },
    "31101305": { i18n_id: "31101305", i18n_sb: "回复自身$1%的血量,同时减少自身下一次受到的伤害,减少值为发动者攻击力的$2%." },
    "32102205": {
        i18n_id: "32102205",
        i18n_sb: "增加$1%的攻击。场上每有一名其他武将阵亡时，你依次获得如下效果：普通攻击后回复自身10%的最大体力；普通攻击会额外造成目标10%最大体力值的伤害，伤害量不会超出自身攻击力；普通攻击后再次进行一次攻击。"
    },
    "35102505": { i18n_id: "35102505", i18n_sb: "0" },
    "10000205": { i18n_id: "10000205", i18n_sb: "造成攻击力伤害,伤害系数$1%,同时封印目标2回合(无法施放技能)." },
    "34100105": {
        i18n_id: "34100105",
        i18n_sb: "对敌方全体造成伤害，伤害系数为$1%；同时增加敌方全体下一次受到的伤害（增加值为发动者攻击力的$2%）、降低敌方全体下一次造成的伤害（减少值为发动者攻击力的$3%），发动者自身失去$4%的血量。"
    },
    "34200805": { i18n_id: "34200805", i18n_sb: "增加自身$1%的智力，同时增加自身$2%的防御力." },
    "37101405": { i18n_id: "37101405", i18n_sb: "造成攻击力伤害,伤害系数$1%,同时吸收伤害值$2%的血量." },
    "33100205": { i18n_id: "33100205", i18n_sb: "造成智力伤害，伤害系数为$1%，该伤害无视$2%防御，且敌方已阵亡人数每多一名，伤害增加$3%." },
