    "341003305": { i18n_id: "341003305", i18n_sb: "造成智力伤害,伤害系数$1%；并减少自身下一次受到的伤害，减少值为$2%." },
    "34101205": { i18n_id: "34101205", i18n_sb: "造成智力伤害,伤害系数$1%." },
