    randomfirstname_75: { i18n_id: "randomfirstname_75", i18n_sb: "咆哮" },
    randomfirstname_85: { i18n_id: "randomfirstname_85", i18n_sb: "秉公无私" },
    randomfirstname_95: { i18n_id: "randomfirstname_95", i18n_sb: "唯我独尊" },
    randomsecondname_10: { i18n_id: "randomsecondname_10", i18n_sb: "曹人" },
    randomsecondname_20: { i18n_id: "randomsecondname_20", i18n_sb: "曹红" },
    randomsecondname_30: { i18n_id: "randomsecondname_30", i18n_sb: "张非" },
    randomsecondname_40: { i18n_id: "randomsecondname_40", i18n_sb: "马呆" },
    randomsecondname_50: { i18n_id: "randomsecondname_50", i18n_sb: "马苏" },
    randomsecondname_60: { i18n_id: "randomsecondname_60", i18n_sb: "太师词" },
    randomsecondname_70: { i18n_id: "randomsecondname_70", i18n_sb: "祖冒" },
    randomsecondname_80: { i18n_id: "randomsecondname_80", i18n_sb: "董拙" },
    randomsecondname_90: { i18n_id: "randomsecondname_90", i18n_sb: "李如" },
    ladder_5: { i18n_id: "ladder_5", i18n_sb: "高智魏王" },
    ladder_15: { i18n_id: "ladder_15", i18n_sb: "三品卫将军" },
    ladder_25: { i18n_id: "ladder_25", i18n_sb: "都尉" },
    ladder_35: { i18n_id: "ladder_35", i18n_sb: "百人将" },
    ladder_45: { i18n_id: "ladder_45", i18n_sb: "什长" },
    ladder_55: { i18n_id: "ladder_55", i18n_sb: "伍长" },
    ladder_65: { i18n_id: "ladder_65", i18n_sb: "伍长" },
    ladder_75: { i18n_id: "ladder_75", i18n_sb: "兵卒" },
    ladder_85: { i18n_id: "ladder_85", i18n_sb: "兵卒" },
    ladder_95: { i18n_id: "ladder_95", i18n_sb: "兵卒" },
    ladder_105: { i18n_id: "ladder_105", i18n_sb: "兵卒" },
    ladder_115: { i18n_id: "ladder_115", i18n_sb: "兵卒" },
    ladder_125: { i18n_id: "ladder_125", i18n_sb: "平民" },
    ladder_135: { i18n_id: "ladder_135", i18n_sb: "平民" },
    xiulian_5: { i18n_id: "xiulian_5", i18n_sb: "坚固贫血丸" },
    xiulian_15: { i18n_id: "xiulian_15", i18n_sb: "大力菊残丸" },
    xiulian_25: { i18n_id: "xiulian_25", i18n_sb: "磐石贫血丸" },
    xiulian_35: { i18n_id: "xiulian_35", i18n_sb: "延年脆骨丸" },
    xiulian_45: { i18n_id: "xiulian_45", i18n_sb: "大智菊残丸" },
    xiulian_55: { i18n_id: "xiulian_55", i18n_sb: "给力逗比丸" },
    xiulian_65: { i18n_id: "xiulian_65", i18n_sb: "坚硬智障丸" },
    xiulian_75: { i18n_id: "xiulian_75", i18n_sb: "万寿脑残丸" },
    xiulian_85: { i18n_id: "xiulian_85", i18n_sb: "大力脆皮丸" },
    xiulian_95: { i18n_id: "xiulian_95", i18n_sb: "铁壁力残丸" },
    xiulian_105: { i18n_id: "xiulian_105", i18n_sb: "无疆力衰丸" },
    xiulian_115: { i18n_id: "xiulian_115", i18n_sb: "大智脆皮丸" },
    xiulian_125: { i18n_id: "xiulian_125", i18n_sb: "怪力残血丸" },
    xiulian_135: { i18n_id: "xiulian_135", i18n_sb: "铜墙嗝屁丸" },
    xiulian_145: { i18n_id: "xiulian_145", i18n_sb: "益气逗比丸" },
