    dialogname551020021: { i18n_id: "dialogname551020021", i18n_sb: "$UserName" },
    dialogname552008011: { i18n_id: "dialogname552008011", i18n_sb: "$UserName" },
    dialogname552016013: { i18n_id: "dialogname552016013", i18n_sb: "司马懿" },
    dialogname552018017: { i18n_id: "dialogname552018017", i18n_sb: "$UserName" },
    dialogname552019019: { i18n_id: "dialogname552019019", i18n_sb: "曹仁" },
    dialogname552020024: { i18n_id: "dialogname552020024", i18n_sb: "司马懿" },
    dialogname553008013: { i18n_id: "dialogname553008013", i18n_sb: "孙乾" },
    dialogname553016011: { i18n_id: "dialogname553016011", i18n_sb: "$UserName" },
    dialogname553018021: { i18n_id: "dialogname553018021", i18n_sb: "$UserName" },
    dialogname553020013: { i18n_id: "dialogname553020013", i18n_sb: "$UserName" },
    dialogname554004015: { i18n_id: "dialogname554004015", i18n_sb: "$UserName" },
    dialogname554012014: { i18n_id: "dialogname554012014", i18n_sb: "牛金" },
    dialogname554018011: { i18n_id: "dialogname554018011", i18n_sb: "$UserName" },
    dialogname554020011: { i18n_id: "dialogname554020011", i18n_sb: "程昱" },
    dialogdesc550004013: { i18n_id: "dialogdesc550004013", i18n_sb: "他让我去魏国看他，这该不会是一个计吧？" },
    dialogdesc550012012: { i18n_id: "dialogdesc550012012", i18n_sb: "不知道。" },
    dialogdesc550016012: { i18n_id: "dialogdesc550016012", i18n_sb: "司马太傅的官是明升反降。" },
    dialogdesc550018013: { i18n_id: "dialogdesc550018013", i18n_sb: "喂，说话啊，不会连话都不能说了吧！" },
    dialogdesc550019013: { i18n_id: "dialogdesc550019013", i18n_sb: "司马太傅有令，活捉蜀国顾问，赏银500！" },
    dialogdesc551004011: { i18n_id: "dialogdesc551004011", i18n_sb: "我这次去魏国帮了司马懿大忙，现在他杀了曹爽，整个魏国的政权都被他控制在手里了。" },
    dialogdesc551008014: { i18n_id: "dialogdesc551008014", i18n_sb: "饭可以乱吃话不能乱说，你这样诋毁上司简直找打！" },
    dialogdesc551016011: { i18n_id: "dialogdesc551016011", i18n_sb: "希望顾问能站在我们这一边。" },
    dialogdesc551019011: { i18n_id: "dialogdesc551019011", i18n_sb: "罪将魏延已被推至法场！" },
    dialogdesc551020021: { i18n_id: "dialogdesc551020021", i18n_sb: "对不起，我不得不这么做！" },
    dialogdesc552008011: { i18n_id: "dialogdesc552008011", i18n_sb: "司马懿在哪！带我去见他！" },
    dialogdesc552016013: { i18n_id: "dialogdesc552016013", i18n_sb: "我不能告诉你。" },
    dialogdesc552018017: { i18n_id: "dialogdesc552018017", i18n_sb: "你说对了！我现在怒得必须砍两个人才能解恨！" },
    dialogdesc552019019: { i18n_id: "dialogdesc552019019", i18n_sb: "太傅快跑！我掩护你！" },
    dialogdesc552020024: { i18n_id: "dialogdesc552020024", i18n_sb: "现在司马家族大权在握，无论天意还是人为，都没办法再改变了……（司马懿挂）" },
    dialogdesc553008013: { i18n_id: "dialogdesc553008013", i18n_sb: "现在蜀国群龙无首，少主年幼，顾问此行万万不可！" },
    dialogdesc553016011: { i18n_id: "dialogdesc553016011", i18n_sb: "光凭蜀国，挑战魏国确实有难度，不如我继续找吴国联盟？" },
    dialogdesc553018021: { i18n_id: "dialogdesc553018021", i18n_sb: "战斗力只有5的渣滓，还想跟我斗！" },
    dialogdesc553020013: { i18n_id: "dialogdesc553020013", i18n_sb: "使者？专门来找我？找我干什么？" },
    dialogdesc554004015: { i18n_id: "dialogdesc554004015", i18n_sb: "我正好手痒，反正你也欠揍！那就来吧！" },
    dialogdesc554012014: { i18n_id: "dialogdesc554012014", i18n_sb: "我们这里交五险一金，工资高、不加班，带薪年假有三个月，你过来就有师长待遇，要不再考虑一下？" },
    dialogdesc554018011: {
        i18n_id: "dialogdesc554018011",
        i18n_sb: "我记得蜀国灭亡，只不过是邓艾带了一队人马，攻打成都。还好我早就写信通知成都的将领做好准备，这下应该没问题了。"
    },
    dialogdesc554020011: { i18n_id: "dialogdesc554020011", i18n_sb: "蜀后主已经投降，并令所有蜀国子民全部投降不得抵抗！" },
