    itemdesc311016: {
        i18n_id: "itemdesc311016",
        i18n_sb: "【强袭】典韦的舍命保驾之技，自残后可狼性大发，属攻击技能，主攻。行动时一般概率触发，消耗自身少量血，即可对敌方单体造成剧烈伤害。"
    },
    itemdesc312020: { i18n_id: "itemdesc312020", i18n_sb: "【肃整】朱灵能让敌人受到深入打击的治军之道，属控场技能，主智。行动前易触发，可使敌方单体下一次受到的伤害增加。" },
    itemdesc351015: { i18n_id: "itemdesc351015", i18n_sb: "【马术】马超攻击为何如此强力的秘诀，属被动技能，主攻。装备后，可增加自身攻击力。" },
    itemdesc322010: { i18n_id: "itemdesc322010", i18n_sb: "【当先】廖化能够先下手为强的秘诀，属控场技能，主攻。行动前易触发，可对敌方单体造成连续两次攻击伤害。" },
    itemdesc331003: {
        i18n_id: "itemdesc331003",
        i18n_sb: "【制衡】孙权的内政方针，能让自己加伤或减伤，属控场技能，主攻和防。行动前易触发，可增加自身下一次造成的伤害，或减少自身下一次受到的伤害。"
    },
    itemdesc332010: { i18n_id: "itemdesc332010", i18n_sb: "【虎娇】大虎卖萌时可使敌人伤及一片，属攻击技能，主智。行动时一般概率触发，可对敌方全体造成智力伤害。" },
    itemdesc341002: { i18n_id: "itemdesc341002", i18n_sb: "【无双】吕布能一招扫灭敌方全军的能力，属攻击技能，主攻。行动时易触发，可对敌方场上全体造成攻击伤害。" },
    itemdesc342005: {
        i18n_id: "itemdesc342005",
        i18n_sb: "【眀策】陈宫能让己方最聪明的战友多出一份力的计策，属控场技能，主智。行动前一般概率触发，可增加场上智最高友军下一次造成的伤害，并让其额外进行一次普通攻击。"
    },
    itemdesc342022: {
        i18n_id: "itemdesc342022",
        i18n_sb: "【狂斧】潘凤能使敌人伤害减弱的伎俩，属控场技能，主攻。行动前一般概率触发，可对敌方单体造成攻击伤害，同时减少其下一次造成的伤害。"
    },
    itemdesc303110: { i18n_id: "itemdesc303110", i18n_sb: "【击溃】以武力取胜的方法之九，已在士兵中普及，属攻击技能，主攻。行动时较困难触发，可对敌方单体造成攻击伤害。" },
    itemdesc363001: { i18n_id: "itemdesc363001", i18n_sb: "【经验银书】能使任意技能获得少量提升的银书。在技能升级界面吃掉后，可获得少量技能经验。" },
    itemdesc351035: { i18n_id: "itemdesc351035", i18n_sb: "【神戟】邪神吕布怒火迸发、一骑当千。不仅提升自身战斗力，更极大扩大了攻击范围。" },
