    dialogdesc551016012: { i18n_id: "dialogdesc551016012", i18n_sb: "大敌当前，你们这样内讧不合适吧！" },
    dialogdesc551019012: { i18n_id: "dialogdesc551019012", i18n_sb: "什么？！" },
    dialogdesc551020022: { i18n_id: "dialogdesc551020022", i18n_sb: "是我心存怨念，才会被人利用魔化，我该谢你替我解脱。" },
    dialogdesc552008012: { i18n_id: "dialogdesc552008012", i18n_sb: "太傅已下定决心灭你，他绝不会见你……" },
    dialogdesc552016014: { i18n_id: "dialogdesc552016014", i18n_sb: "你又玩我！这次必须弄死你！" },
    dialogdesc552018021: { i18n_id: "dialogdesc552018021", i18n_sb: "一路杀到现在，我感觉浑身充满了力量~！" },
    dialogdesc5520190110: { i18n_id: "dialogdesc5520190110", i18n_sb: "今天神佛都挡不住我弄死司马懿！" },
    dialogdesc552020025: {
        i18n_id: "dialogdesc552020025",
        i18n_sb: "你骗我！你这个骗子！！别以为你死了我就拿你没办法！从今天起！我发誓！发毒誓！无论你的子孙做什么事情，我都要破坏它！如果你地下有知，我就要让你死不瞑目！"
    },
    dialogdesc553008014: { i18n_id: "dialogdesc553008014", i18n_sb: "我还万万没想到呢！这件事我决定了，谁都别拦我！" },
    dialogdesc553016012: { i18n_id: "dialogdesc553016012", i18n_sb: "吴国三番两次背叛我国，顾问此想法太过幼稚！" },
    dialogdesc553018022: { i18n_id: "dialogdesc553018022", i18n_sb: "七星灯不在我这里，在王平处……" },
    dialogdesc553020014: { i18n_id: "dialogdesc553020014", i18n_sb: "如果你愿意和我们合作的话，主人愿意把力量借给你。" },
    dialogdesc554004021: { i18n_id: "dialogdesc554004021", i18n_sb: "剑阁已经被我们重重包围，拿下你们指日可待！" },
    dialogdesc554012015: { i18n_id: "dialogdesc554012015", i18n_sb: "要在现代世界我说不定已经投诚了，在三国世界的话，看打！" },
    dialogdesc554018012: { i18n_id: "dialogdesc554018012", i18n_sb: "程昱军师已带兵攻入成都。" },
    dialogdesc554020012: { i18n_id: "dialogdesc554020012", i18n_sb: "我不信！" },
