    xiulian_217: { i18n_id: "xiulian_217", i18n_sb: "益寿逗比丸" },
    xiulian_227: { i18n_id: "xiulian_227", i18n_sb: "睿智残血丸" },
    xiulian_237: { i18n_id: "xiulian_237", i18n_sb: "巨力脑残丸" },
