    xiulian_267: { i18n_id: "xiulian_267", i18n_sb: "开天菊残丸" },
    xiulian_277: { i18n_id: "xiulian_277", i18n_sb: "金刚贫血丸" },
    xiulian_287: { i18n_id: "xiulian_287", i18n_sb: "齐天脆骨丸" },
    xiulian_297: { i18n_id: "xiulian_297", i18n_sb: "绝圣菊残丸" },
    xiulian_307: { i18n_id: "xiulian_307", i18n_sb: "巨力逗比丸" },
