    dialogname551004013: { i18n_id: "dialogname551004013", i18n_sb: "满宠" },
    dialogname551008022: { i18n_id: "dialogname551008022", i18n_sb: "$UserName" },
    dialogname551016013: { i18n_id: "dialogname551016013", i18n_sb: "于禁" },
    dialogname551019013: { i18n_id: "dialogname551019013", i18n_sb: "张春华" },
    dialogname551020023: { i18n_id: "dialogname551020023", i18n_sb: "$UserName" },
    dialogname552008013: { i18n_id: "dialogname552008013", i18n_sb: "$UserName" },
    dialogname552016015: { i18n_id: "dialogname552016015", i18n_sb: "李通" },
    dialogname552019011: { i18n_id: "dialogname552019011", i18n_sb: "司马懿" },
    dialogname552019021: { i18n_id: "dialogname552019021", i18n_sb: "$UserName" },
    dialogname553004011: { i18n_id: "dialogname553004011", i18n_sb: "$UserName" },
    dialogname553008021: { i18n_id: "dialogname553008021", i18n_sb: "$UserName" },
    dialogname553016013: { i18n_id: "dialogname553016013", i18n_sb: "$UserName" },
    dialogname553019011: { i18n_id: "dialogname553019011", i18n_sb: "$UserName" },
    dialogname553020015: { i18n_id: "dialogname553020015", i18n_sb: "$UserName" },
    dialogname554008011: { i18n_id: "dialogname554008011", i18n_sb: "典满" },
    dialogname554012021: { i18n_id: "dialogname554012021", i18n_sb: "$UserName" },
    dialogname554018013: { i18n_id: "dialogname554018013", i18n_sb: "$UserName" },
    dialogname554020013: { i18n_id: "dialogname554020013", i18n_sb: "程昱" },
    dialogdesc550004015: { i18n_id: "dialogdesc550004015", i18n_sb: "我好歹和你们太傅也有几年交情，更何况你是个送信的，你说话的语气能不能不要太任性？" },
    dialogdesc550012014: { i18n_id: "dialogdesc550012014", i18n_sb: "不知道。" },
    dialogdesc550016014: { i18n_id: "dialogdesc550016014", i18n_sb: "他位高权重，陛下不得不防他，所以名义是把他升级到国务院秘书长，实际上他的兵权全没了。" },
    dialogdesc550018015: { i18n_id: "dialogdesc550018015", i18n_sb: "司马老贼！受死吧！" },
    dialogdesc550019021: { i18n_id: "dialogdesc550019021", i18n_sb: "我发现玩计谋，我比小司马还是差了几个档次。" },
    dialogdesc551004013: { i18n_id: "dialogdesc551004013", i18n_sb: "你去魏国干什么？怎么签证的？怎么通过安全部门申请的？" },
    dialogdesc551008022: { i18n_id: "dialogdesc551008022", i18n_sb: "不是还有我嘛，你们都慌什么！" },
    dialogdesc551016013: { i18n_id: "dialogdesc551016013", i18n_sb: "攘外必先安内，除掉宫内的谋反势力就是现在的当务之急！" },
    dialogdesc551019013: { i18n_id: "dialogdesc551019013", i18n_sb: "顾问还是回去吧，就算你现在赶到法场，也什么都来不及了。" },
    dialogdesc551020023: { i18n_id: "dialogdesc551020023", i18n_sb: "你知道野心家到底是谁吗？" },
    dialogdesc552008013: { i18n_id: "dialogdesc552008013", i18n_sb: "他不见我！我就打到他出来为止！" },
    dialogdesc552016015: { i18n_id: "dialogdesc552016015", i18n_sb: "司马太傅说你是魏国最大敌人，必须除之后快！" },
    dialogdesc552019011: { i18n_id: "dialogdesc552019011", i18n_sb: "既然你纠缠不清，那我就告诉你真相，你想知道什么？" },
    dialogdesc552019021: { i18n_id: "dialogdesc552019021", i18n_sb: "你这个骗子！！什么保护历史！什么消灭野心家，一切你都只是为了自己！" },
    dialogdesc553004011: {
        i18n_id: "dialogdesc553004011",
        i18n_sb: "原来司马懿把我弄到这个世界，就是为了帮他填坑！现在司马家族把魏国大权全占了，他死了轻松，我不会放过他的！只要我不能回到未来，我绝对不会让司马家族占领魏国！"
    },
    dialogdesc553008021: { i18n_id: "dialogdesc553008021", i18n_sb: "蜀国现在军心不稳，让我一个人去挑魏国，难度也太高了。" },
    dialogdesc553016013: { i18n_id: "dialogdesc553016013", i18n_sb: "没试过怎么知道不行，让开！" },
    dialogdesc553019011: { i18n_id: "dialogdesc553019011", i18n_sb: "野心家是怎么魔化军师的？" },
    dialogdesc553020015: { i18n_id: "dialogdesc553020015", i18n_sb: "对不起！我不和任何人合作！你走吧！" },
    dialogdesc554008011: { i18n_id: "dialogdesc554008011", i18n_sb: "汉中已经被我们占领了，劝你们还是早点投降吧！" },
    dialogdesc554012021: { i18n_id: "dialogdesc554012021", i18n_sb: "激战中还有空来拍我马屁，看样子是撑不住了。" },
    dialogdesc554018013: { i18n_id: "dialogdesc554018013", i18n_sb: "这不可能！我的信应该早就到了，为什么他们没做好准备？！" },
    dialogdesc554020013: {
        i18n_id: "dialogdesc554020013",
        i18n_sb: "打败你们的是，蜀后主昏庸无道，朝政腐败不堪，民心涣散，并不是我兵力有多强，而是蜀国已从内部坏死到不可挽回的地步。"
    },
