    "312012502": {
        i18n_id: "312012502",
        i18n_sb: "【酒诗】七步即可成诗的曹植，饮酒作诗，属卖血技能，主智。受伤时易触发，受到伤害后，为自己与友军增加下一回合造成的伤害；阵亡时仅限一次，复活后增加自身攻击。现五阶状态下，复活后免疫下一次伤害。"
    },
    "312012504": { i18n_id: "312012504", i18n_sb: "自身" },
    "8710150501": { i18n_id: "8710150501", i18n_sb: "开启觉醒宝箱" },
