    itemdesc312002: {
        i18n_id: "itemdesc312002",
        i18n_sb: "【奇策】荀攸可伤敌亦可疗伤的奇能，属攻击技能，主智。行动时一般概率触发，可对敌方场上全体造成智力伤害，或回复己方场上全体一定血量。"
    },
    itemdesc312022: { i18n_id: "itemdesc312022", i18n_sb: "【宣烈】鲍勋以死明谏之烈，属卖血技能，主防。阵亡时，可对敌方单体造成防御伤害。" },
    itemdesc321013: { i18n_id: "itemdesc321013", i18n_sb: "【枪舞】张星彩可扰乱敌人全军的枪法，属攻击技能，主智。行动时一般概率触发，可对敌方场上全体造成智力伤害。" },
    itemdesc322017: { i18n_id: "itemdesc322017", i18n_sb: "【淑慎】防御最低的敌人最怕看到的就是甘夫人的死，属卖血技能，主防。阵亡时，可对场上防最低敌军造成防御伤害。" },
    itemdesc331025: {
        i18n_id: "itemdesc331025",
        i18n_sb: "【国色】大乔拥有让人无法行动的美貌，属控场技能，主智。行动前一般概率触发，可对敌方单体造成智力伤害，并且让其无法行动2回合。"
    },
    itemdesc332015: { i18n_id: "itemdesc332015", i18n_sb: "【引兵】能够削弱敌方攻最高的人，属控场技能，主攻。行动前易触发，可减少场上攻最高敌军下一次造成的伤害。" },
    itemdesc341004: { i18n_id: "itemdesc341004", i18n_sb: "【青囊】能获得血最少友军的信任，属控场技能，主智。行动前易触发，可回复场上血最少己方武将一定血量。" },
    itemdesc353002: { i18n_id: "itemdesc353002", i18n_sb: "【谋阵】能使人智力大增的阵法，属被动技能，主智。装备后，可增加自身智力。" },
    itemdesc303102: { i18n_id: "itemdesc303102", i18n_sb: "【追击】以武力取胜的方法之二，已在士兵中普及，属攻击技能，主攻。行动时较困难触发，可对敌方单体造成攻击伤害。" },
    itemdesc302102: { i18n_id: "itemdesc302102", i18n_sb: "【混元】能使人增加防御力的阵法，属被动技能，主防。装备后，可增加自身防御力。" },
    itemdesc351032: { i18n_id: "itemdesc351032", i18n_sb: "【帷幕】能在战场保护自己的屏障，属被动技能，主防。装备后，可增加自身防御力。" },
    itemdesc331026: {
        i18n_id: "itemdesc331026",
        i18n_sb: "【好施】鲁肃慷慨解囊救人水火的品德，能在乱世之中保队友平安无事，属控场技能，主智。行动前易触发，能降低己方场上全体下一次受到的伤害。"
    },
