    dialogname551020024: { i18n_id: "dialogname551020024", i18n_sb: "德古拉魏延" },
    dialogname552008021: { i18n_id: "dialogname552008021", i18n_sb: "$UserName" },
    dialogname552016021: { i18n_id: "dialogname552016021", i18n_sb: "$UserName" },
    dialogname552019012: { i18n_id: "dialogname552019012", i18n_sb: "$UserName" },
    dialogname552019022: { i18n_id: "dialogname552019022", i18n_sb: "司马懿" },
    dialogname553004012: { i18n_id: "dialogname553004012", i18n_sb: "吴兰" },
    dialogname553012011: { i18n_id: "dialogname553012011", i18n_sb: "$UserName" },
    dialogname553016021: { i18n_id: "dialogname553016021", i18n_sb: "$UserName" },
    dialogname553019012: { i18n_id: "dialogname553019012", i18n_sb: "王平" },
    dialogname553020016: { i18n_id: "dialogname553020016", i18n_sb: "\\u9B54\\xB7\\u9A6C\\u8D85" },
    dialogname554008012: { i18n_id: "dialogname554008012", i18n_sb: "$UserName" },
    dialogname554016011: { i18n_id: "dialogname554016011", i18n_sb: "朱灵" },
    dialogname554018014: { i18n_id: "dialogname554018014", i18n_sb: "满宠" },
    dialogname554020014: { i18n_id: "dialogname554020014", i18n_sb: "$UserName" },
    dialogdesc550004016: { i18n_id: "dialogdesc550004016", i18n_sb: "休想花言巧语蒙混过关！扫把星！受死吧！" },
    dialogdesc550012015: { i18n_id: "dialogdesc550012015", i18n_sb: "什么病？" },
    dialogdesc550016015: { i18n_id: "dialogdesc550016015", i18n_sb: "哈哈哈他也有今天，算了，我去慰问慰问他，省得他心情不好病情加重！" },
    dialogdesc550018016: { i18n_id: "dialogdesc550018016", i18n_sb: "非礼个节操！刺杀个病人，太不要脸了！" },
    dialogdesc550020011: { i18n_id: "dialogdesc550020011", i18n_sb: "司马懿这个混蛋！他把我弄来第一是为了对付刺客！第二是为了调虎离山，让我去吸引国内大将的眼球，他去弄曹爽！" },
    dialogdesc551004014: { i18n_id: "dialogdesc551004014", i18n_sb: "我好歹也算堂堂蜀国的顾问，你凭什么来盘问我？" },
    dialogdesc551012011: { i18n_id: "dialogdesc551012011", i18n_sb: "我出去几天，怎么蜀国上下一片混乱，到底怎么了？" },
    dialogdesc551016014: { i18n_id: "dialogdesc551016014", i18n_sb: "要杀魏延，必须先过我这关！" },
    dialogdesc551019014: { i18n_id: "dialogdesc551019014", i18n_sb: "闪开！挡我者死！！" },
    dialogdesc551020024: { i18n_id: "dialogdesc551020024", i18n_sb: "（吟诗）考功就前，永遏羽山……" },
    dialogdesc552008021: { i18n_id: "dialogdesc552008021", i18n_sb: "司马懿！你给我出来！我们有太多账要好好算算！" },
    dialogdesc552016021: { i18n_id: "dialogdesc552016021", i18n_sb: "司马懿！今天你再也跑不了了！" },
    dialogdesc552019012: { i18n_id: "dialogdesc552019012", i18n_sb: "为什么你知道野心家会改变三国历史？" },
    dialogdesc552019022: { i18n_id: "dialogdesc552019022", i18n_sb: "历史与现代息息相关，也许因为蝴蝶效应，没有晋国，你也不会出现。" },
    dialogdesc553004012: { i18n_id: "dialogdesc553004012", i18n_sb: "顾问让我们去攻打魏国？怎么可能？太冒失了！" },
    dialogdesc553012011: { i18n_id: "dialogdesc553012011", i18n_sb: "我必须在司马家族称帝前，杀入魏国！" },
    dialogdesc553016021: { i18n_id: "dialogdesc553016021", i18n_sb: "你说的对，现在我们是魏国的第一目标，吴国还没我们强大，找他们来垫背，也没多大意思。" },
    dialogdesc553019012: { i18n_id: "dialogdesc553019012", i18n_sb: "七星灯灭了以后，军师就没办法抵抗野心家的力量了！" },
    dialogdesc553020016: { i18n_id: "dialogdesc553020016", i18n_sb: "主人有令，如果你不肯合作，我就只能杀了你！" },
    dialogdesc554008012: { i18n_id: "dialogdesc554008012", i18n_sb: "看着你的脸庞，真想用热翔糊你一脸啊！" },
    dialogdesc554016011: { i18n_id: "dialogdesc554016011", i18n_sb: "现在我军已到了强弩之末，粮草缺乏、军无斗志，战斗再这样焦灼下去，只能撤退或者议和了……" },
    dialogdesc554018014: {
        i18n_id: "dialogdesc554018014",
        i18n_sb: "有巫士算命说不可能有将领攻入成都，他们正在举国欢庆呢，被程昱军师一举击破！你们都城都保不住，我劝你还是别守了！"
    },
    dialogdesc554020014: {
        i18n_id: "dialogdesc554020014",
        i18n_sb: "哈哈哈哈哈，别人是心想事成，我发现我在这个世界，是想什么败什么。我喜欢貂蝉，貂蝉死了，在蜀国当顾问，蜀国亡了，我呆在这里到底算什么！"
    },
